-- Prospective studio analytics, reviewed experiments and manual financial workflow.
alter table public.cineo_view_sessions add column source text not null default 'unknown', add column experiments jsonb not null default '[]', add column finished boolean not null default false;
alter table public.cineo_qualified_views add column source text not null default 'unknown', add column experiments jsonb not null default '[]';
create index cineo_view_sessions_episode_time_idx on public.cineo_view_sessions(episode_id,created_at);
create index cineo_views_creator_day_idx on public.cineo_qualified_views(creator_id,day);
create table public.cineo_watch_spans(session_id uuid not null references public.cineo_view_sessions(id) on delete cascade, seq integer not null, from_ms integer not null, to_ms integer not null, primary key(session_id,seq));
create table public.cineo_follower_events(id bigint generated always as identity primary key, creator_id uuid not null references auth.users(id) on delete cascade, delta integer not null check(delta in(-1,1)), created_at timestamptz not null default now());
create index cineo_follower_events_creator_time_idx on public.cineo_follower_events(creator_id,created_at);
create table public.cineo_studio_goals(id uuid primary key default gen_random_uuid(),creator_id uuid not null references auth.users(id) on delete cascade,metric text not null check(metric in('views','followers')),target bigint not null check(target between 1 and 1000000000000),deadline date not null,created_at timestamptz not null default now());
create index cineo_studio_goals_owner_idx on public.cineo_studio_goals(creator_id);
create table public.cineo_creator_roles(creator_id uuid not null references auth.users(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('editor','producer','finance')),created_at timestamptz not null default now(),primary key(creator_id,user_id),check(creator_id<>user_id));
create index cineo_creator_roles_member_idx on public.cineo_creator_roles(user_id);
create table public.cineo_ab_tests(id uuid primary key default gen_random_uuid(),creator_id uuid not null references auth.users(id) on delete cascade,show_id bigint not null references public.cineo_shows(id) on delete cascade,kind text not null check(kind in('title','cover')),baseline_title text not null,baseline_cover text not null default '',alternative text not null,status text not null default 'pending' check(status in('pending','active','rejected','stopped')),reason text not null default '',created_at timestamptz not null default now(),reviewed_at timestamptz);
create unique index cineo_ab_one_active_idx on public.cineo_ab_tests(show_id,kind) where status='active';
create index cineo_ab_creator_idx on public.cineo_ab_tests(creator_id,created_at desc);
create table public.cineo_ab_exposures(test_id uuid not null references public.cineo_ab_tests(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,day date not null default (now() at time zone 'America/Sao_Paulo')::date,variant integer not null check(variant in(0,1)),seen boolean not null default false,started boolean not null default false,qualified boolean not null default false,id bigint generated always as identity primary key,unique(test_id,user_id,day));
create table public.cineo_rights_documents(id uuid primary key default gen_random_uuid(),creator_id uuid not null references auth.users(id) on delete cascade,show_id bigint not null references public.cineo_shows(id) on delete cascade,created_by uuid references auth.users(id) on delete set null,name text not null,kind text not null check(kind in('license','music','actor','other')),path text not null,mime text not null,expires_on date,created_at timestamptz not null default now());
create index cineo_rights_owner_idx on public.cineo_rights_documents(creator_id,created_at desc);
create table public.cineo_copyright_cases(id uuid primary key default gen_random_uuid(),claimant_id uuid not null references auth.users(id) on delete cascade,creator_id uuid not null references auth.users(id) on delete cascade,show_id bigint not null references public.cineo_shows(id) on delete cascade,message text not null,proof_id uuid references public.cineo_rights_documents(id) on delete set null,status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')),reply text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index cineo_copyright_creator_idx on public.cineo_copyright_cases(creator_id,status);
create index cineo_copyright_claimant_idx on public.cineo_copyright_cases(claimant_id,created_at desc);
create table public.cineo_payout_rules(id integer primary key check(id=1),enabled boolean not null default false,minimum_cents bigint check(minimum_cents between 1 and 100000000),terms text not null default '',revision integer not null default 1,updated_at timestamptz not null default now());
insert into public.cineo_payout_rules(id) values(1);
create table public.cineo_studio_audit(id bigint generated always as identity primary key,creator_id uuid references auth.users(id) on delete set null,actor_id uuid references auth.users(id) on delete set null,action text not null,detail jsonb not null default '{}',created_at timestamptz not null default now());
create index cineo_studio_audit_owner_idx on public.cineo_studio_audit(creator_id,created_at desc);
create table public.cineo_monthly_settlements(id uuid primary key default gen_random_uuid(),creator_id uuid not null references auth.users(id) on delete cascade,month date not null check(extract(day from month)=1),views bigint not null,gross_cents bigint not null check(gross_cents>=0),approved_cents bigint not null check(approved_cents between 0 and gross_cents),reason text not null,reviewed_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(creator_id,month));
create table public.cineo_withdrawals(id uuid primary key default gen_random_uuid(),creator_id uuid not null references auth.users(id) on delete cascade,amount_cents bigint not null check(amount_cents>0),pix_envelope jsonb not null,pix_hint text not null,terms_revision integer not null,status text not null default 'requested' check(status in('requested','approved','rejected','cancelled','paid')),note text not null default '',payment_reference text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index cineo_withdrawals_owner_idx on public.cineo_withdrawals(creator_id,created_at desc);
create unique index cineo_payment_reference_idx on public.cineo_withdrawals(payment_reference) where status='paid';
do $$declare t text;begin foreach t in array array['cineo_watch_spans','cineo_follower_events','cineo_studio_goals','cineo_creator_roles','cineo_ab_tests','cineo_ab_exposures','cineo_rights_documents','cineo_copyright_cases','cineo_payout_rules','cineo_studio_audit','cineo_monthly_settlements','cineo_withdrawals'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
grant usage,select on sequence public.cineo_follower_events_id_seq,public.cineo_ab_exposures_id_seq,public.cineo_studio_audit_id_seq to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('cineo-rights-private','cineo-rights-private',false,5242880,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;


